    using namespace browser_library;std::size_t checks{};const auto check=[&](bool value,const char* message){++checks;if(!value)throw std::runtime_error("check "+std::to_string(checks)+": "+message);};const auto rejects=[&](auto action,const char* message){bool failed{};try{action();}catch(...){failed=true;}check(failed,message);};
